// TDA quiz. a[0] is always the right answer: options are shuffled when shown.
// r lists the items of data/tda.json that back the answer.
(function (root) {
  'use strict';
  const S = 'Showdown', P = 'Piatti e fiches', M = 'Mani e livelli', D = 'Errori di distribuzione', B = 'Puntate e rilanci', T = 'Azione e turno', E = 'Condotta e penalità', K = 'Procedure del dealer';
  const QUIZ = [
    { id: 'sd1', cat: S, r: ['R13'], q: 'Allo showdown un giocatore dice "hai vinto tu" e spinge le carte scoperte verso il centro, ma ha il punto migliore. Che fai?', a: ['Le carte parlano: la sua mano vince se è la migliore', 'Ha rinunciato al piatto: vince l\'altro giocatore', 'Dichiarare "hai vinto tu" vincola solo dopo che il dealer ha letto le mani', 'Il dealer chiama il floor, che decide se la dichiarazione vale'], why: 'Le carte parlano. Dichiarazioni come "fold", "hai vinto" o "prenditi il piatto" non sono vincolanti allo showdown.' },
    { id: 'sd2', cat: S, r: ['R13'], q: 'Chi può far notare un errore nella lettura di un punto?', a: ['Chiunque, che sia o no nella mano', 'Solo chi è ancora coinvolto nella mano', 'Solo il floor, su chiamata del dealer', 'Solo chi ha chiamato l\'ultima puntata al river'], why: 'La regola 13 dice che ogni persona, nella mano o no, dovrebbe esprimersi se pensa ci sia un errore nella lettura o nell\'assegnazione del piatto.' },
    { id: 'sd3', cat: S, r: ['R14'], q: 'Quando una mano è mostrata correttamente?', a: ['Tutte le carte scoperte sul tavolo, leggibili da dealer e giocatori', 'Il giocatore dichiara il punto ad alta voce e mostra almeno una carta', 'Basta girare la carta che fa il punto, se il dealer la legge', 'Il dealer ha visto le carte, anche solo per un attimo, prima del muck'], why: 'Servono insieme due condizioni: tutte le carte girate sul tavolo e leggibili chiaramente da dealer e giocatori.' },
    { id: 'sd4', cat: S, r: ['R13', 'R14'], q: 'Allo showdown, cosa dovresti fare come dealer quando le mani sono scoperte?', a: ['Leggere e annunciare il valore delle mani', 'Lasciare che sia il giocatore col punto migliore a dichiararlo, e leggere solo se c\'è contestazione', 'Annunciare solo la mano vincente e rimettere le altre nel muck', 'Annunciare le mani solo se c\'è stato un all-in'], why: 'I dealer dovrebbero leggere e annunciare il valore delle mani allo showdown. Nel testo inglese sta nella regola 13, nella traduzione italiana nella 14-A.' },
    { id: 'sd5', cat: S, r: ['R14'], q: 'Una mano è stata mostrata correttamente ed è ovviamente vincente, ma il giocatore non se ne accorge. Puoi ucciderla?', a: ['No, il dealer non può uccidere una mano mostrata correttamente', 'Sì, se il giocatore non reclama il piatto entro qualche secondo', 'Sì, se nel frattempo l\'avversario ha già buttato le carte nel muck', 'Sì, ma solo se tutti i giocatori in mano sono d\'accordo'], why: 'Regola 14-C: i dealer non possono uccidere una mano correttamente mostrata e ovviamente vincente.' },
    { id: 'sd6', cat: S, r: ['R16'], q: 'Un giocatore mostra una sola carta, che però gli darebbe il punto vincente. Che fai?', a: ['Gli dici di mostrarle entrambe; se rifiuta, chiami il floor', 'Gli assegni il piatto, una carta basta se fa il punto', 'Gli uccidi subito la mano, perché non l\'ha mostrata tutta', 'Scopri tu l\'altra carta e leggi il punto al tavolo'], why: 'Regola 16-A: il dealer avvisa dell\'obbligo di mostrarle entrambe. Se il giocatore rifiuta, si chiama il floor.' },
    { id: 'sd7', cat: S, r: ['R16', 'R60'], q: 'Un giocatore punta e subito scarta le carte, convinto di aver vinto, ma c\'è ancora un avversario in mano. Che fai?', a: ['Trattieni le carte e chiami il floor', 'Le metti nel muck: la mano è morta', 'Gli restituisci la puntata e continui', 'Assegni il piatto all\'avversario'], why: 'Regola 16-B: il dealer dovrebbe trattenere le carte e chiamare il floor (è un\'eccezione alla regola 60). Se finiscono nel muck e non sono identificabili al 100%, il giocatore è fuori e non riavrà le puntate chiamate, ma la parte non ancora chiamata gli viene restituita.' },
    { id: 'sd8', cat: S, r: ['R16'], q: 'Cosa fai con le mani perdenti che sono state mostrate, prima di assegnare il piatto?', a: ['Le giri a faccia in giù e le tieni riconoscibili, fuori dal muck', 'Le metti subito nel muck, tanto il dealer le ha già lette', 'Le lasci scoperte sul tavolo fino all\'inizio della mano dopo', 'Le restituisci ai giocatori finché il piatto non è assegnato'], why: 'Regola 16-C: restano a faccia in giù e riconoscibili finché non è determinato il vincitore e assegnato il piatto.' },
    { id: 'sd9', cat: S, r: ['R15'], q: 'Un giocatore allo showdown spinge le carte coperte, ma poi cambia idea. Le carte sono ancora recuperabili e identificabili al 100%. Può mostrarle?', a: ['Sì, scartarle coperte non elimina automaticamente la mano', 'No, appena spinge le carte in avanti la sua mano è morta', 'Sì, ma solo se il floor le ha viste prima dello scarto', 'Solo se l\'avversario non ha ancora mostrato il suo punto'], why: 'Regola 15: scartare coperto non elimina automaticamente la mano. È morta quando il dealer la mette nel muck o la rende comunque irrecuperabile.' },
    { id: 'sd10', cat: S, r: ['R17', 'I17'], q: 'Heads-up al turn: il più corto va all-in e l\'altro chiama. Cosa fai?', a: ['Scopri entrambe le mani, bruci e giri il river', 'Bruci e giri il river, poi fai scoprire le mani', 'Aspetti lo showdown e fai mostrare prima chi ha puntato', 'Fai scoprire solo chi è all-in, poi giri il river'], why: 'Regola 17, Esempio 1: si scoprono tutte le mani appena un giocatore è all-in e non è possibile altra azione, poi si brucia e si gira il river.' },
    { id: 'sd11', cat: S, r: ['I17'], q: 'Preflop A va all-in, B e C chiamano e hanno ancora gettoni. Si scoprono le carte?', a: ['No: B e C possono ancora puntare, si scopre a fine azione', 'Sì, si scoprono tutte subito perché c\'è un all-in', 'Solo quelle di A, quelle di B e C restano coperte', 'Sì, ma solo se B e C sono d\'accordo a scoprirle'], why: 'Regola 17, Esempio 2: non si mostrano perché B e C hanno ancora gettoni, quindi è possibile altra azione.' },
    { id: 'sd12', cat: S, r: ['I17'], q: 'C\'è un side pot tra B e C e un piatto principale con A in all-in. Cosa assegni per primo?', a: ['Il side pot tra B e C, poi il principale', 'Il principale con A, poi il side pot tra B e C', 'Prima il più grande dei due, poi l\'altro', 'È indifferente, basta che siano separati'], why: 'Illustration Addendum, regola 17: si assegna per primo il side pot, poi il main pot. Le carte di A non restano coperte in attesa del side pot: si scoprono subito con le altre.' },
    { id: 'sd13', cat: S, r: ['R17'], q: 'Un giocatore in all-in, a mano finita, vuole buttare le carte senza mostrarle. Può?', a: ['No, nessun giocatore in all-in o che ha chiamato può farlo', 'Sì, se pensa di aver perso e nessuno chiede di vederla', 'Sì, se l\'avversario ha già mostrato una mano migliore', 'Sì, con il permesso degli altri giocatori in mano'], why: 'Regola 17: nessun giocatore, in all-in o che abbia chiamato tutte le puntate, può gettare le carte senza mostrarle correttamente.' },
    { id: 'sd14', cat: S, r: ['R18'], q: 'Showdown senza all-in, al river c\'è stata una puntata e un rilancio. Chi mostra per primo?', a: ['Chi ha rilanciato: ultima azione aggressiva al river', 'Chi ha puntato per primo, perché ha aperto il river', 'Il primo in mano a sinistra del bottone, come sempre', 'Chi ha chiamato il rilancio, perché ha pagato per vedere'], why: 'Regola 18-A: deve mostrare per primo chi ha fatto l\'ultima azione aggressiva nell\'ultimo giro di puntate. Vale se nessuno mostra spontaneamente: il TD può imporre questo ordine.' },
    { id: 'sd15', cat: S, r: ['R18'], q: 'Al turn c\'è stata una grossa puntata, al river tutti check. Chi mostra per primo?', a: ['Il primo in mano a sinistra del bottone', 'Chi ha puntato al turn, ultima aggressione', 'Il bottone, che parla per ultimo al river', 'Il big blind, se è ancora nella mano'], why: 'Regola 18-A: conta solo il river. Senza azione aggressiva al river mostra chi sarebbe il primo ad agire. Vale se nessuno mostra spontaneamente: il TD può imporre questo ordine.' },
    { id: 'sd16', cat: S, r: ['R18'], q: 'Showdown senza all-in: tutti i giocatori tranne uno buttano le carte coperte. L\'ultimo deve mostrare?', a: ['No, vince senza dover mostrare', 'Sì, deve mostrare almeno una carta', 'Sì, se ha rilanciato al river', 'Sì, se ha ancora gettoni dietro'], why: 'Regola 18-B: lo showdown è uncontested e l\'ultima mano viva vince senza dover mostrare. Con un all-in invece vale la regola 17.' },
    { id: 'sd17', cat: S, r: ['R19'], q: 'Chi ha chiamato al river vuole vedere la mano di chi ha puntato. Quando ne ha diritto?', a: ['Se ha ancora le carte o le ha mostrate', 'Sempre, anche se ha già buttato le carte', 'Mai di diritto: decide sempre il floor', 'Solo se nessun altro ha chiamato prima'], why: 'Regola 19-B: è un diritto inalienabile, a condizione che chi ha chiamato abbia ancora le carte o le abbia mostrate.' },
    { id: 'sd18', cat: S, r: ['R19'], q: 'Un giocatore ha buttato le carte coperte nel muck e chiede di vedere quelle di un altro. Ne ha diritto?', a: ['No, ha perso ogni diritto', 'Sì, se ha chiamato al river', 'Sì, se lo chiede prima dell\'assegnazione', 'Decide il dealer'], why: 'Regola 19-A: chi non ha più le carte o le ha gettate coperte perde ogni diritto di chiedere di vedere le altre mani.' },
    { id: 'sd19', cat: S, r: ['R20'], q: 'Il board è la mano migliore per tutti. Un giocatore vuole dividere e dice "gioco il board" senza scoprire le carte. Basta?', a: ['No, deve mostrare entrambe le carte per partecipare al piatto', 'Sì, basta dichiararlo prima che il dealer spinga il piatto', 'Sì, se l\'altro giocatore in mano è d\'accordo a dividere', 'Basta mostrarne una, tanto il punto lo fa il board'], why: 'Regola 20: per giocare il board il giocatore deve mostrare entrambe le carte.' },
    { id: 'p1', cat: P, r: ['R21'], q: 'Hold\'em, piatto diviso con una fiche in più. A chi va?', a: ['Al primo a sinistra del bottone tra chi divide', 'Al giocatore più vicino al bottone dal lato destro, tra chi divide', 'Al giocatore con più gettoni tra chi divide', 'Alla mano con il kicker migliore'], why: 'Regola 21-A: nei giochi con board la fiche dispari va al primo a sinistra del bottone.' },
    { id: 'p2', cat: P, r: ['R21'], q: 'Da quando vale la regola 21-D sulla "posizione peggiore" e a quali giochi si applica?', a: ['È una novità 2026 e vale solo nei giochi non standard non high-low', 'È una novità 2026 e vale per tutti i giochi, anche high-low', 'Vale solo nell\'hold\'em e negli altri giochi con il board', 'C\'era già prima del 2026 e vale solo in heads-up'], why: 'La parte D è stata aggiunta nel 2026 e riguarda solo i giochi non standard non high-low. L\'hold\'em resta sulla 21-A.' },
    { id: 'p3', cat: P, r: ['R21'], q: 'Prima di assegnare un gettone dispari, cosa va fatto?', a: ['Cambiarlo nella più bassa denominazione in gioco', 'Toglierlo dal gioco e assegnare il resto del piatto', 'Chiamare sempre il floor prima di toccarlo', 'Darlo subito al bottone, senza cambiarlo'], why: 'Regola 21: per prima cosa i gettoni dispari vengono cambiati nella più bassa denominazione in gioco.' },
    { id: 'p4', cat: P, r: ['R23'], q: 'Due giocatori pareggiano in un side pot e nel principale. Come dividi?', a: ['Ogni piatto si divide separatamente', 'Sommi i piatti e dividi una volta sola', 'Il side pot va tutto al primo a sinistra del bottone', 'Dividi solo il principale'], why: 'Regola 23: ogni side pot viene diviso separatamente.' },
    { id: 'p5', cat: P, r: ['R24', 'R25'], q: 'Fino a quando si può contestare la lettura di una mano mostrata?', a: ['Fino a quando inizia la mano successiva', 'Fino alla fine del livello in cui è giocata', 'Fino a un minuto dopo l\'assegnazione, sempre', 'Fino al flop della mano successiva'], why: 'Regola 24: la lettura si può discutere finché non inizia la mano successiva, che comincia al primo riffle, al pulsante del mescolatore o al cambio dealer (25-B).' },
    { id: 'p6', cat: P, r: ['R24'], q: 'Un errore di conteggio nell\'assegnazione del piatto fino a quando si può discutere?', a: ['Fino a quando c\'è azione sostanziale nella mano successiva', 'Solo fino al primo riffle della mano successiva', 'Fino alla fine del livello in cui è stata giocata', 'Mai, una volta spinto il piatto l\'assegnazione è definitiva'], why: 'Regola 24: gli errori di conteggio si discutono fino all\'azione sostanziale nella mano successiva.' },
    { id: 'p7', cat: P, r: ['R24'], q: 'La mano finisce proprio all\'inizio di una pausa. Quanto tempo c\'è per contestare?', a: ['Un minuto dopo l\'assegnazione del piatto', 'Cinque minuti dall\'assegnazione del piatto', 'Fino alla ripresa del gioco dopo la pausa', 'Fino a quando il dealer non lascia il tavolo'], why: 'Regola 24: se la mano termina durante una pausa, il diritto di discussione cessa un minuto dopo l\'assegnazione del piatto.' },
    { id: 'p8', cat: P, r: ['R26'], q: 'Chip race: da dove si comincia e quanti gettoni si danno al massimo a ogni giocatore?', a: ['Dal posto 1, al massimo un gettone a giocatore', 'Dal bottone, al massimo due gettoni a giocatore', 'Dal giocatore con più gettoni, senza limite', 'Dal big blind, al massimo un gettone a testa'], why: 'Regola 26-A: il chip race comincia dal posto numero 1, con al massimo un gettone per giocatore.' },
    { id: 'p9', cat: P, r: ['R26'], q: 'Durante il chip race un giocatore perde i suoi ultimi gettoni. È eliminato?', a: ['No, riceve un gettone del taglio più basso ancora in gioco', 'Sì, è eliminato e prende il piazzamento di quel momento', 'No, rientra con uno stack pari a un big blind', 'Decide il dealer se dargli un gettone o eliminarlo'], why: 'Regola 26-A: nessuno può essere eliminato dal chip race. Riceve un gettone della più bassa denominazione ancora in corso.' },
    { id: 'p10', cat: P, r: ['R27'], q: 'Come devono stare i gettoni dei giocatori?', a: ['In pile verticali ordinate da 20 pezzi della stessa denominazione', 'In pile da 20, ma mescolando i valori per risparmiare spazio', 'In pile da 10 della stessa denominazione, per contarle meglio', 'In pile da 20, con i gettoni di valore più basso davanti'], why: 'Regola 27-A, rafforzata nel 2026: pile ordinate da 20 pezzi della stessa denominazione, con i gettoni di valore più alto visibili.' },
    { id: 'p11', cat: P, r: ['R62'], q: 'Quando un giocatore può chiedere il conteggio preciso dello stack di un avversario?', a: ['Solo se è il suo turno e ha di fronte un all-in', 'In qualunque momento, basta chiederlo al dealer', 'Solo se è in heads-up con l\'avversario', 'Solo se l\'avversario è d\'accordo'], why: 'Regola 62: il conteggio preciso si chiede solo nel proprio turno, facendo fronte a un all-in.' },
    { id: 'p12', cat: P, r: ['R62'], q: 'Il giocatore in all-in non vuole contare i suoi gettoni e chi deve decidere chiede il conteggio. Che succede?', a: ['Li conta il dealer o il floor', 'Deve contarli per forza', 'Non si contano e il giocatore di turno decide alla cieca', 'È una penalità automatica'], why: 'Regola 62: chi è in all-in non è tenuto a contare. Su richiesta conta il dealer o il floor.' },
    { id: 'p13', cat: P, r: ['R66'], q: 'Trovi dei gettoni e non si riesce a capire di chi sono. Dove vanno?', a: ['Eliminati dal gioco e riportati nell\'inventario del torneo', 'Ai giocatori del tavolo, in parti uguali', 'Nello stack del giocatore più vicino', 'Nel piatto della mano in corso, fino a trovare il proprietario'], why: 'Regola 66: i gettoni trovati senza proprietario certo escono dal gioco e tornano nell\'inventario.' },
    { id: 'p14', cat: P, r: ['R64'], q: 'A va all-in, B chiama, poi spunta un gettone nascosto di A. Chi decide?', a: ['Il TD decide se fa parte dell\'azione accettata', 'Quel gettone resta sempre ad A, fuori dall\'azione', 'B deve pagarlo sempre, perché ha chiamato l\'all-in', 'Il gettone va sempre nel piatto, chiunque vinca'], why: 'Regola 64: decide il TD. Se non conta, A non viene pagato per quel gettone se vince, e se perde il gettone non lo salva.' },
    { id: 'm1', cat: M, r: ['R25'], q: 'Quando comincia ufficialmente una mano?', a: ['Al primo riffle, al pulsante del mescolatore o al cambio dealer', 'Alla prima carta distribuita a un giocatore, cioè allo small blind', 'Quando i bui e le ante sono sul tavolo', 'Alla fine della mano precedente, quando il piatto è assegnato'], why: 'Regola 25-B: le mani iniziano al primo riffle, alla pressione del pulsante del mescolatore automatico o al cambio dealer.' },
    { id: 'm2', cat: M, r: ['R25'], q: 'Il clock segna il cambio livello durante una mano. Quando valgono i nuovi limiti?', a: ['Dalla mano successiva', 'Dal prossimo giro di puntate, anche a mano in corso', 'Subito, se nessuno ha ancora fatto azione', 'Dalla prossima pausa programmata'], why: 'Regola 25-A: il nuovo limite di puntata si applica alla mano successiva.' },
    { id: 'm3', cat: M, r: ['R25'], q: 'Non ti sei accorto del cambio livello. Un giocatore te lo fa notare prima che ci sia azione sostanziale. Che fai?', a: ['Applichi subito i limiti corretti', 'Finisci la mano al vecchio livello', 'Dichiari misdeal', 'Dici che può farlo solo il floor'], why: 'Regola 25-C: chiunque può farlo notare e il dealer deve applicare subito i limiti corretti. Dopo azione sostanziale, la mano continua al livello precedente (25-B).' },
    { id: 'm4', cat: M, r: ['R32'], q: 'Quando un giocatore deve essere al posto per avere una mano attiva?', a: ['Quando viene data l\'ultima carta della distribuzione iniziale', 'Quando viene distribuita la sua prima carta della mano', 'Quando il dealer fa il primo riffle, cioè all\'inizio della mano', 'Quando tocca a lui parlare per la prima volta nella mano'], why: 'Regola 32: deve essere al posto quando viene distribuita l\'ultima carta della distribuzione iniziale.' },
    { id: 'm5', cat: M, r: ['R32'], q: 'Un giocatore non era al posto durante la distribuzione. Cosa succede ai suoi bui e all\'ante?', a: ['Vanno nel piatto e la mano viene foldata', 'Gli vengono restituiti, la mano non conta', 'Restano davanti a lui per la mano dopo', 'Si ridistribuisce la mano a tutto il tavolo'], why: 'Regola 32: non può guardare le carte, la mano è foldata a fine distribuzione, e bui e ante vanno nel piatto.' },
    { id: 'm6', cat: M, r: ['R36'], q: 'In heads-up chi è small blind e chi riceve l\'ultima carta?', a: ['Il bottone è small blind e riceve l\'ultima carta', 'Il bottone è big blind e riceve la prima carta', 'Il bottone è small blind e riceve la prima carta', 'Il big blind riceve l\'ultima carta'], why: 'Regola 36-C: in heads-up il piccolo buio è di bottone, e l\'ultima carta viene distribuita al bottone.' },
    { id: 'm7', cat: M, r: ['R36'], q: 'In heads-up chi parla per primo preflop e dopo il flop?', a: ['Preflop il bottone, dopo il flop l\'altro', 'Sempre il bottone', 'Sempre il big blind', 'Preflop il big blind, dopo il flop il bottone'], why: 'Regola 36-C: lo small blind è di bottone, agisce per primo preflop e per ultimo in tutti gli altri giri.' },
    { id: 'm8', cat: M, r: ['R36'], q: 'Il bottone è stato spostato per sbaglio due volte e c\'è già azione sostanziale. Che si fa?', a: ['Si continua e il bottone resta dov\'è, anche alla mano dopo', 'Misdeal, perché la posizione del bottone è sbagliata', 'Si continua, ma alla mano dopo il bottone torna indietro', 'Si torna indietro nell\'azione e si sposta il bottone'], why: 'Regola 36-A: prima dell\'azione sostanziale si corregge, dopo il gioco continua e l\'errore resta.' },
    { id: 'm9', cat: M, r: ['R36'], q: 'Posto 9 bottone, posto 1 SB, posti 2 e 3 vuoti, posto 4 BB. Il posto 1 viene eliminato. Dove va il bottone se ci sono giocatori in arrivo?', a: ['Al posto 3, con SB al 4 e BB al 5', 'Al posto 1, con SB al 2 e BB al 3', 'Resta al posto 9, con il buio piccolo morto', 'Al posto 4, con SB al 5 e BB al 6'], why: 'È l\'esempio della regola 36-B: il bottone avanza sui posti vuoti, così i nuovi possono occupare i posti 1 e 2 senza stare tra bottone e bui.' },
    { id: 'm10', cat: M, r: ['R9', 'R11'], q: 'Un nuovo giocatore viene fatto sedere tra lo small blind e il bottone. Riceve le carte?', a: ['No, lì non riceve le carte', 'Sì, sempre', 'Sì, se paga un buio', 'Solo se il floor lo ordina'], why: 'Regole 9-A e 11-A: i giocatori nuovi ricevono le carte ovunque siano, tranne che tra small blind e bottone.' },
    { id: 'm11', cat: M, r: ['R28'], q: 'Un giocatore chiede di cambiare il mazzo. Puoi accontentarlo?', a: ['No, i giocatori non possono chiederlo', 'Sì, se tutti i giocatori in mano sono d\'accordo', 'Sì, una volta ogni livello', 'Sì, se il mazzo ha più di tre mani giocate'], why: 'Regola 28: il mazzo si cambia al cambio dealer, al cambio livello o come prescrive la casa. I giocatori non possono chiederlo.' },
    { id: 'm12', cat: M, r: ['R30'], q: 'Mano finita, un giocatore chiede di vedere quale sarebbe stato il river. Che fai?', a: ['Non lo fai: il rabbit hunting non è consentito', 'Lo giri solo se tutti i giocatori sono d\'accordo', 'Lo giri a patto che il mazzo non sia stato mischiato', 'Lo mostri solo al giocatore che lo chiede'], why: 'Regola 30: mostrare le carte che sarebbero uscite non è consentito.' },
    { id: 'm13', cat: M, r: ['R31'], q: 'Viene chiamato il tempo. Di quanto tempo dispone il giocatore?', a: ['Fino a 25 secondi più un conto alla rovescia di 5', 'Fino a 60 secondi in tutto', 'Fino a 25 secondi, e allo scadere la mano è morta', 'Fino a 15 secondi più un conto alla rovescia di 10'], why: 'Regola 31: fino a 25 secondi, più 5 di conto alla rovescia. Il TD può modificare il tempo.' },
    { id: 'm14', cat: M, r: ['R31'], q: 'Il tempo scade mentre il giocatore sta facendo fronte a una puntata. Cosa succede?', a: ['La mano è morta', 'Si considera call', 'Si considera check', 'Ha altri 30 secondi'], why: 'Regola 31: se sta facendo fronte a una puntata la mano è morta. Se non ha puntate di fronte, vale check.' },
    { id: 'd1', cat: D, r: ['R37'], q: 'Quale di questi NON è un misdeal?', a: ['Due carte consecutive al giocatore di bottone', 'La prima carta al posto sbagliato', 'Due o più carte girate al contrario (boxed) nella distribuzione iniziale', 'Carte a un giocatore che non ne ha diritto'], why: 'Regola 37-B: dare due carte consecutive al bottone è consentito. Gli altri sono casi di misdeal della 37-A.' },
    { id: 'd2', cat: D, r: ['R37'], q: 'Hold\'em: scopri per errore la primissima carta che distribuisci, quella allo small blind. È misdeal?', a: ['Sì, è una delle prime 2 carte uscite dal mazzo', 'No, si continua e la carta resta a quel giocatore', 'No, si sostituisce la carta con la prossima del mazzo', 'Solo se se ne accorge un giocatore prima di agire'], why: 'Regola 37-A: è misdeal se il dealer scopre per errore una delle prime 2 carte uscite dal mazzo, oppure altre 2 carte coperte qualunque. Una sola carta scoperta dopo le prime due non rientra in questa voce.' },
    { id: 'd3', cat: D, r: ['R37'], q: 'Dopo un misdeal, cosa succede nella nuova mano?', a: ['Re-play esatto: bottone fermo, limiti uguali, niente nuovi giocatori', 'Il bottone avanza di un posto, ma i limiti restano uguali', 'Bottone fermo, ma si siedono i giocatori nuovi arrivati', 'Bottone fermo, ma si applicano i limiti del nuovo livello se è scattato'], why: 'Regola 37-C: la nuova mano è l\'esatto re-play della precedente.' },
    { id: 'd4', cat: D, r: ['R37', 'R38', 'R40', 'I40'], q: 'Un giocatore scopre di avere tre carte, ma c\'è già azione sostanziale. Si può dichiarare misdeal?', a: ['No, la mano prosegue e la sua è morta', 'Sì, sempre', 'Sì, se lo chiede lui', 'Sì, se il floor è d\'accordo con tutti'], why: 'Regola 37-D: dopo azione sostanziale non si può dichiarare misdeal, a meno che il mazzo sia compromesso. L\'Esempio 1-B della regola 40 è proprio il caso delle tre carte.' },
    { id: 'd5', cat: D, r: ['R37'], q: 'A metà mano trovi nel mazzo due assi di picche. Che succede?', a: ['Fermi il gioco e restituisci tutte le puntate, anche dopo azione sostanziale', 'Togli una delle due carte e continui, perché c\'è già stata azione sostanziale', 'Finisci la mano e poi fai cambiare il mazzo prima della prossima', 'Fermi il gioco e restituisci solo le puntate dell\'ultimo giro'], why: 'Regola 37-E: il mazzo è compromesso. Il gioco viene fermato e tutte le puntate restituite, indipendentemente dall\'azione sostanziale.' },
    { id: 'd6', cat: D, r: ['R38'], q: 'Quale sequenza È azione sostanziale?', a: ['Fold e call', 'Fold e fold', 'Check e check', 'Un solo raise'], why: 'Regola 38: bastano due azioni di cui almeno una con gettoni, oppure tre azioni qualunque. Fold e call ha due azioni, una con gettoni.' },
    { id: 'd7', cat: D, r: ['R38'], q: 'Tre giocatori in fila foldano. C\'è azione sostanziale?', a: ['Sì, tre azioni qualunque bastano', 'No, nessuno ha messo gettoni nel piatto', 'Solo se uno dei tre è il big blind', 'Solo se succede dopo il flop'], why: 'Regola 38-B: qualunque combinazione di 3 azioni è azione sostanziale.' },
    { id: 'd8', cat: D, r: ['R39'], q: 'Il giocatore di bottone ha una carta sola e non ha ancora agito, ma c\'è azione sostanziale. Che succede?', a: ['La carta mancante può essere rimpiazzata', 'Misdeal, perché ha ricevuto una carta sola', 'La sua mano è morta, anche se non ha agito', 'Si ridistribuisce la mano a tutti i giocatori'], why: 'Regola 39: al bottone le carte mancanti possono essere rimpiazzate anche dopo azione sostanziale. Se però agisce con troppe poche carte, la mano è morta.' },
    { id: 'd9', cat: D, r: ['R40', 'I40'], q: 'Dopo azione sostanziale una mano è morta perché ha troppe poche carte. Quante carte bruci prima del flop?', a: ['Una sola', 'Due, per ripristinare l\'ordine originale del mazzo', 'Nessuna, dopo azione sostanziale non si brucia', 'Una per ogni carta mancante al giocatore'], why: 'Regola 40: si brucia una e una sola carta per strada. Lo scopo è proteggere lo stub, non l\'ordine delle carte.' },
    { id: 'd10', cat: D, r: ['R41'], q: 'Giri un flop di 4 carte. Che fai?', a: ['Floor: mischi le 4 coperte, lui ne sceglie una come bruciata, le altre 3 sono il flop', 'Togli la quarta carta e la metti come prossima bruciata, le prime 3 restano il flop', 'Chiami il floor: le 4 carte tornano nello stub, rimischi e giri un flop nuovo', 'Misdeal, perché il flop ha una carta in più di quelle previste'], why: 'Regola 41-A: si chiama il floor, si mischiano le 4 carte coperte, il floor ne sceglie a caso una come prossima bruciata e le altre tre compongono il flop.' },
    { id: 'd11', cat: D, r: ['R41'], q: 'Hai girato il flop senza bruciare e nessuno ha ancora agito. Che fai?', a: ['Mischi le 3 coperte: una va bruciata, il flop sono le altre 2 più la carta dopo', 'Bruci la carta successiva e lasci il flop così com\'è, nessuno ha agito', 'Rimetti le 3 carte nello stub, rimischi, bruci e giri un flop nuovo', 'Misdeal, perché il flop è stato girato senza bruciare'], why: 'Regola 41-B: senza alcuna azione, le 3 carte si mischiano coperte, una diventa bruciata e si aggiunge la carta successiva dello stub.' },
    { id: 'd12', cat: D, r: ['R41'], q: 'Hai girato il flop senza bruciare, ma il primo giocatore ha già fatto check. Che succede?', a: ['Si procede con le 3 carte, e per il turn bruci una sola carta', 'Si rimischiano le 3 carte e si rifà il flop come se nessuno avesse agito', 'Si procede, ma per il turn bruci due carte invece di una', 'Misdeal, perché il flop è stato girato senza bruciare'], why: 'Regola 41-B: con almeno un\'azione, anche un solo check, si procede con le 3 carte iniziali e per il turn si brucia una sola carta.' },
    { id: 'd13', cat: D, r: ['RP5'], q: 'Giri il flop prima che l\'azione preflop sia finita. Come rimedi?', a: ['La bruciata resta, il flop torna nello stub, rimischi e rigiri senza bruciare', 'Lasci il flop sul tavolo e lo usi dopo la fine dell\'azione preflop', 'Il flop torna nello stub con la bruciata, rimischi, bruci e giri di nuovo', 'Bruci un\'altra carta e giri tre carte nuove dallo stub, senza rimischiare'], why: 'RP-5-A: la carta bruciata resta al suo posto, le carte tornano nello stub rimischiato e il nuovo flop si gira senza bruciare ancora.' },
    { id: 'd14', cat: D, r: ['RP5'], q: 'Giri il turn prima che l\'azione del flop sia finita. Come rimedi?', a: ['La bruciata resta, il turn torna nello stub, rimischi e lo rigiri senza bruciare', 'La tieni da parte come river e giri un nuovo turn dopo la bruciata', 'La lasci come turn, tanto l\'azione del flop deve ancora finire', 'Rimetti nello stub sia il turn che la bruciata, rimischi, bruci e rigiri'], why: 'RP-5-B: la bruciata rimane, la carta torna nello stub, che si rimischia. Il nuovo turn è la prima carta, senza altre bruciate.' },
    { id: 'd15', cat: D, r: ['RP4'], q: 'Lo stub ti cade e si disordina, ma non si mischia col muck. Qual è la prima scelta?', a: ['Provare a ricostruire l\'ordine originale, se possibile', 'Fare subito uno stub nuovo mescolando le carte cadute', 'Rimischiare tutto insieme al muck e alle bruciate', 'Continuare a distribuire con le carte come sono'], why: 'RP-4: prima si tenta di ricostruire l\'ordine. Se non si può, si rifà lo stub con le sole sue carte, mischiando e tagliando.' },
    { id: 'd16', cat: D, r: ['R41'], q: 'Devi rimescolare lo stub durante una mano. Come?', a: ['A carte coperte, senza esporle', 'A carte scoperte, così tutti vedono che nulla è cambiato', 'A carte coperte, ma facendo prima vedere la carta in cima ai giocatori', 'A carte coperte, mescolando anche il muck con lo stub'], why: 'Regola 41-D: per proteggere il gioco lo stub si rimescola con le carte rivolte verso il basso e non esposte.' },
    { id: 'b1', cat: B, r: ['R42', 'I42-A'], q: 'Un giocatore dice "mille" e subito dopo spinge 2.000 in gettoni. Qual è la puntata?', a: ['1.000: il primo metodo usato definisce la puntata', '2.000: quando ci sono i gettoni contano i gettoni', 'Decide lui quale delle due intendeva', '2.000, perché si prende sempre l\'importo più alto'], why: 'Regola 42-A: se usa entrambi i metodi, il primo effettuato definisce la puntata. Se dichiarazione e gettoni si contraddicono o non è chiaro, decide il TD.' },
    { id: 'b2', cat: B, r: ['R42'], q: 'Se dichiarazione e gettoni arrivano nello stesso momento, cosa prevale?', a: ['Una dichiarazione verbale chiara e ragionevole', 'Sempre i gettoni, che sono sul tavolo e si vedono', 'L\'importo più alto tra voce e gettoni', 'L\'importo più basso, a tutela di chi chiama'], why: 'Regola 42-A: se simultanei, ha la precedenza una chiara e ragionevole dichiarazione verbale, altrimenti si considerano i gettoni.' },
    { id: 'b3', cat: B, r: ['R43', 'R46'], q: 'Di fronte a una puntata un giocatore mette in silenzio un solo gettone più grande del call. Cos\'è?', a: ['Un call', 'Un rilancio del massimo', 'Un rilancio minimo', 'Una puntata non valida'], why: 'Regole 43 e 46: un gettone singolo più grande, senza aver dichiarato "raise", è un call.' },
    { id: 'b4', cat: B, r: ['R46'], q: 'Di fronte a una puntata dice "raise" senza importo prima che il gettone tocchi il tavolo. Quanto è il rilancio?', a: ['Il massimo possibile per quel gettone', 'Il rilancio minimo valido', 'Un call: il gettone è più grande della puntata', 'Una puntata non valida, il giocatore deve ripetere'], why: 'Regola 46: se dichiara "raise" ma nessun valore, il rilancio è il massimo possibile per la denominazione di quel gettone.' },
    { id: 'b5', cat: B, r: ['R46'], q: 'Nessuna puntata di fronte. Un giocatore mette in silenzio un gettone da 5.000. Quanto ha puntato?', a: ['5.000', 'Il minimo, con il resto restituito', 'Un check: senza parlare non c\'è puntata', 'Una puntata valida solo se il giocatore conferma a voce'], why: 'Regola 46: senza puntate di fronte, un gettone singolo in silenzio è una puntata del massimo valore di quel gettone.' },
    { id: 'b6', cat: B, r: ['R44'], q: 'Come si esegue correttamente un rilancio in no-limit?', a: ['In un solo movimento, o dichiarando il totale prima dei gettoni', 'Prima metti il call, poi aggiungi il rilancio in un secondo movimento', 'Dicendo «call e rilancio» e mettendo i gettoni un po\' alla volta', 'In più movimenti, basta dire «raise» prima del secondo'], why: 'Regola 44: ammontare totale in un solo movimento, oppure dichiarando il totale prima. Il rilancio in due movimenti è stato eliminato.' },
    { id: 'b7', cat: B, r: ['R45'], q: 'Apertura da 1.000. Un giocatore con altri gettoni dietro mette in silenzio 1.400. Che azione è?', a: ['Call: non arriva al 50% del rilancio', 'Rilancio a 1.400, è sopra la puntata', 'Rilancio obbligato al minimo, a 2.000', 'Puntata non valida, gli si rende tutto'], why: 'Regola 45-A: 400 oltre il call è meno del 50% di 1.000. È l\'esempio del regolamento: è un call, salvo "raise" dichiarato prima.' },
    { id: 'b8', cat: B, r: ['R45'], q: 'Apertura da 1.000. Un giocatore mette in silenzio 1.500 con altri gettoni dietro. Che azione è?', a: ['Deve completare il rilancio minimo a 2.000', 'Call, e gli si restituiscono i 500 in più', 'Rilancio a 1.500, valido perché supera il 50%', 'Call, perché il rilancio non è stato dichiarato'], why: 'Regola 45-A: chi rilancia del 50% o più, ma meno del minimo, deve completare fino al rilancio minimo.' },
    { id: 'b9', cat: B, r: ['R45'], q: 'A apre per 2.000, B dichiara "raise 8.000". Qual è la puntata totale di B?', a: ['8.000', '10.000', '6.000', '4.000'], why: 'Regola 45-B: senza altre informazioni, "raise" e un importo indica l\'intera puntata.' },
    { id: 'b10', cat: B, r: ['I45'], q: 'Bui 100-200. Dopo il flop A punta 600, B rilancia a 1.600, C rilancia a 3.600. Qual è il rilancio minimo per D?', a: ['A 5.600', 'A 7.200', 'A 4.200', 'A 4.600'], why: 'Illustration Addendum regola 45, Esempio 1: l\'ultimo rilancio è di 2.000, quindi 3.600 + 2.000.' },
    { id: 'b11', cat: B, r: ['R47', 'I47'], q: 'Da chiamare 1.100. Un giocatore mette in silenzio un gettone da 1.000 e uno da 500. Che azione è?', a: ['Call: togliendo il 500 resta meno del call', 'Rilancio obbligato, perché supera il call di 400', 'Rilancio a 1.500, perché è più del call', 'Undercall, il giocatore deve completare'], why: 'Regola 47-A: se togliendo il gettone più piccolo resta meno del call, tutti i gettoni servono ed è un call.' },
    { id: 'b12', cat: B, r: ['I47'], q: 'Bui 250-500, rilancio a 1.100. Un giocatore con altri gettoni dietro mette in silenzio 1.000 e cinque da 100, per 1.500. Che azione è?', a: ['Rilancio obbligato a 1.700', 'Call, e gli si restituiscono 400', 'Rilancio a 1.500, così com\'è', 'Rilancio obbligato a 2.200'], why: 'Esempio 2 dell\'Addendum alla regola 47: il minimo è 600, il 50% è 300. Da 1.400 in su deve completare a 1.700.' },
    { id: 'b13', cat: B, r: ['R63'], q: 'La puntata è 325. Un giocatore con altri gettoni dietro mette 500 e 25 aspettandosi 200 di resto. Che azione è?', a: ['Rilancio a 650', 'Call con 200 di resto', 'Rilancio a 525', 'Puntata non valida'], why: 'Regola 63: i gettoni messi senza dichiarare rischiano di restare nel piatto. Per la regola 47 è un rilancio a 650.' },
    { id: 'b14', cat: B, r: ['R48'], q: 'Un giocatore con gettoni davanti di una puntata precedente, di fronte a un rilancio, li ritira chiaramente. Può foldare?', a: ['No, è vincolato a call o raise', 'Sì, sempre, finché non ha parlato', 'Sì, se rimette i gettoni e poi folda', 'Sì, se non ha detto nulla prima'], why: 'Regola 48-B: chi ritira chiaramente i gettoni di una puntata precedente è vincolato a call o raise.' },
    { id: 'b15', cat: B, r: ['R49', 'I49'], q: 'Bui 50-100, dopo il flop. A punta 100, B all-in 125, C chiama, D all-in 200, E chiama. L\'azione torna ad A. Può rilanciare?', a: ['Sì, fa fronte a 100 in più: è un rilancio pieno', 'No, gli all-in corti non riaprono mai l\'azione a chi ha già agito', 'Solo se ha più gettoni di tutti quelli in mano', 'No, può solo chiamare i 100 in più o foldare'], why: 'Regola 49, Esempio 1: gli all-in corti sommati arrivano a un rilancio pieno e riaprono i rilanci per A.' },
    { id: 'b16', cat: B, r: ['I49'], q: 'Bui 50-100, dopo il flop. A punta 300, B all-in 500, C all-in 650, D all-in 800, E chiama. Qual è il rilancio minimo per F?', a: ['A 1.100', 'A 1.300', 'A 950', 'A 1.600'], why: 'Regola 49, Esempio 2: nessun all-in è un rilancio pieno, quindi la misura resta 300: 800 + 300.' },
    { id: 'b17', cat: B, r: ['R50'], q: 'In no-limit quanti rilanci sono permessi?', a: ['Nessun limite', 'Quattro per giro', 'Tre, poi il giro è chiuso', 'Dipende dal numero di giocatori in mano'], why: 'Regola 50: nei giochi no-limit e pot-limit non c\'è limite al numero di rilanci.' },
    { id: 'b18', cat: B, r: ['R51'], q: 'Un giocatore chiede quanto deve chiamare, tu sbagli e dici meno. Lui chiama. Quanto deve mettere?', a: ['L\'importo corretto: resta obbligato, salvo decisione del TD', 'Quello che hai detto tu, perché l\'errore è stato del dealer', 'Può ritirare il call, visto che l\'informazione era sbagliata', 'Paga il banco la differenza'], why: 'Regola 51: chi chiama deve accertare l\'importo ed è obbligato alla puntata corretta, anche con un\'informazione sbagliata. Il TD può applicare la regola 1.' },
    { id: 'b19', cat: B, r: ['R53'], q: 'B ha rilanciato a 8.000, nel proprio turno C dice solo "call". Quanto deve mettere?', a: ['8.000', 'Quanto ha messo per primo', 'Lo decide il floor', 'La puntata di apertura'], why: 'Regola 53-A: le dichiarazioni generiche nel proprio turno vincolano all\'azione corretta e completa.' },
    { id: 'b20', cat: B, r: ['R53', 'I53'], q: 'Dopo il flop, in 4, A apre per 8.000 e B mette in silenzio 2.000. Che succede?', a: ['Undercall sull\'apertura: deve fare il call completo di 8.000', 'Può riprendere i 2.000 e foldare, senza perdere niente', 'A discrezione del TD può foldare e perdere i 2.000 messi', 'È un call da 2.000 e il resto torna nel suo stack'], why: 'Regola 53-B: l\'undercall di fronte alla puntata di apertura va tassativamente adeguato al call completo.' },
    { id: 'b21', cat: B, r: ['R53'], q: 'Preflop, quale puntata è la puntata di apertura?', a: ['Il grande buio', 'Il primo rilancio', 'Il piccolo buio', 'Non c\'è puntata di apertura preflop'], why: 'Regola 53-B: nei giochi con i bui il grande buio rappresenta la puntata di apertura pre-flop.' },
    { id: 'b22', cat: B, r: ['R54'], q: 'Bui 100-200. Dopo il flop A apre di 600, B rilancia a 1.000. C e D chiamano, poi te ne accorgi prima del turn. Che fai?', a: ['Porti le puntate a 1.200 per tutti', 'Lasci 1.000 per tutti, ormai hanno chiamato', 'Riporti tutto a 600, il rilancio non vale', 'Porti a 1.200 solo B, gli altri restano a 1.000'], why: 'Regola 54-A: una puntata sotto il minimo si corregge in tutte le posizioni nel giro in corso. Una volta girato il turn, l\'errore resta.' },
    { id: 'b23', cat: B, r: ['R56'], q: 'In no-limit un giocatore ti chiede quanto c\'è nel piatto. Glielo conti?', a: ['No, in no-limit i dealer non contano il piatto', 'Sì, ma solo se tocca a lui e deve ancora agire', 'Sì, ma solo se la puntata non è all-in', 'Sì, lo conti a voce senza stendere i gettoni'], why: 'Regola 56-A: il conteggio del piatto spetta solo nei giochi pot-limit.' },
    { id: 'b24', cat: B, r: ['R56'], q: 'In no-limit un giocatore dichiara "pot". Che succede?', a: ['Non è valida, ma lo vincola a una puntata valida', 'Vale come puntata di tutto il piatto, come nel pot-limit', 'È un check, perché la dichiarazione non vale', 'È un all-in, perché ha dichiarato «pot»'], why: 'Regola 56-D: non è una puntata valida ma vincola a una puntata valida, almeno il minimo, e può essere soggetta a penalità. Se sta facendo fronte a una puntata deve fare un rilancio valido.' },
    { id: 'b25', cat: B, r: ['R57'], q: 'Non c\'è nessuna puntata e il giocatore dice "call". Cos\'è?', a: ['Un check', 'Una puntata minima', 'Un fold', 'Un rilancio'], why: 'Regola 57-A: se non ha puntate di fronte e dice "call", è un check.' },
    { id: 'b26', cat: B, r: ['R57'], q: 'Non c\'è nessuna puntata e il giocatore dice "raise". Cos\'è?', a: ['Deve fare almeno una puntata minima valida', 'È un check, perché non c\'è niente da rilanciare', 'È un all-in, per tutti i gettoni che ha', 'Deve puntare almeno il doppio del big blind'], why: 'Regola 57-B: se dichiara "raise" deve fare almeno una puntata minima valida.' },
    { id: 'b27', cat: B, r: ['R57'], q: 'Il giocatore dice "check" mentre ha di fronte una puntata. Cosa può fare?', a: ['Call o fold, ma non rilanciare', 'Solo fold, il check non è valido', 'Qualunque azione, anche rilanciare', 'È automaticamente un fold'], why: 'Regola 57: chi dichiara "check" facendo fronte a una puntata può fare call o fold, ma non rilanciare.' },
    { id: 'b28', cat: B, r: ['R58'], q: 'Un giocatore mette dei gettoni, poi torna allo stack ad aggiungerne altri. Com\'è?', a: ['String bet: non è ammesso', 'Valido se non ha ancora parlato', 'Valido se non ha detto nulla', 'Un rilancio regolare'], why: 'Regola 58: non sono ammessi string bet, nemmeno per i rilanci.' },
    { id: 'b29', cat: B, r: ['R59'], q: 'Bui 200-400, nel piatto ci sono 3.000. Il giocatore dice "punto cinque". Quanto ha puntato?', a: ['500', '5.000', '50', 'Quanto dice lui dopo'], why: 'Regola 59: vale il maggiore importo ragionevole minore o uguale al piatto. Con il piatto sotto 5.000 la puntata è 500.' },
    { id: 'b30', cat: B, r: ['R59'], q: 'Bui 200-400, nel piatto ci sono 6.000. Il giocatore dice "punto cinque". Quanto ha puntato?', a: ['5.000', '500', '50', 'Va chiamato il floor per forza'], why: 'Regola 59: con il piatto da 5.000 in su la puntata è 5.000. Nel "piatto" contano anche le puntate davanti ai giocatori.' },
    { id: 't1', cat: T, r: ['R52'], q: 'Un\'azione fatta nel proprio turno può essere ritirata?', a: ['No, è vincolante e i gettoni restano nel piatto', 'Sì, se nessuno dopo di lui ha ancora fatto un\'azione', 'Sì, se è stato un errore evidente e lo dice subito', 'Sì, una volta a mano'], why: 'Regola 52-A: l\'azione nel proprio turno, a voce o con i gettoni, è vincolante.' },
    { id: 't2', cat: T, r: ['R55', 'I55-A1'], q: 'Il posto 6 rilancia fuori turno mentre tocca al posto 5. Che fai?', a: ['Riporti l\'azione al 5: il rilancio del 6 vale se l\'azione non cambia', 'Il rilancio del 6 è annullato per sempre e lui riprende i gettoni', 'Il posto 5 viene saltato e l\'azione continua dopo il 6', 'Riporti l\'azione al 5, e il rilancio del 6 resta valido in ogni caso'], why: 'Regola 55-A1: l\'azione torna al giocatore corretto. L\'azione fuori turno è vincolante se non cambia l\'azione fino a chi ha agito fuori turno.' },
    { id: 't3', cat: T, r: ['I55-A1'], q: 'Il posto 6 rilancia fuori turno, l\'azione torna al posto 5 e il posto 5 rilancia a sua volta. Cosa può fare il posto 6?', a: ['L\'azione è cambiata: riprende i gettoni e ha tutte le opzioni', 'Deve lasciare i suoi gettoni nel piatto e può solo chiamare', 'Può solo chiamare il nuovo rilancio, non può rilanciare', 'Deve foldare, perché ha agito fuori turno e l\'azione è cambiata'], why: 'Esempio 1 dell\'Addendum 55-A1: se l\'azione cambia, i gettoni possono essere restituiti e il giocatore può chiamare, rilanciare o foldare.' },
    { id: 't4', cat: T, r: ['R55'], q: 'Un fold fuori turno è vincolante?', a: ['Sì, anche se poi l\'azione cambia', 'Solo se l\'azione non cambia, come gli altri', 'No, mai: un\'azione fuori turno non vale', 'Solo dopo il flop'], why: 'Regola 55-A1: un fold fuori turno è vincolante, a differenza di check, call e raise, che valgono solo se l\'azione non cambia.' },
    { id: 't5', cat: T, r: ['R55', 'R38', 'I55-A2'], q: 'Un giocatore viene saltato, ha tempo per parlare e non dice nulla finché alla sua sinistra c\'è azione sostanziale fuori turno. Che succede?', a: ['Vale l\'azione fuori turno, e sulla mano saltata decide il floor', 'Si torna indietro annullando tutte le azioni fatte fuori turno', 'Il giocatore saltato è considerato all-in per tutto lo stack', 'Misdeal, perché c\'è stata azione sostanziale fuori turno'], why: 'Regola 55-A2: il giocatore saltato deve difendere il suo diritto. Se ha avuto un tempo ragionevole e resta zitto, l\'azione fuori turno è vincolante e il floor decide sulla sua mano: anche mano morta o sole azioni passive.' },
    { id: 't6', cat: T, r: ['R55', 'I55-B'], q: 'Heads-up: il giocatore B fa check fuori turno, poi A punta. Cosa può fare B?', a: ['Solo chiamare o foldare', 'Anche rilanciare, è heads-up', 'Solo foldare, ha fatto check', 'Niente, la sua mano è morta'], why: 'Regola 55-B: se agisce passivamente fuori turno non può rilanciare in quel giro.' },
    { id: 't7', cat: T, r: ['R60'], q: 'Il primo a parlare dopo il flop folda senza puntate di fronte. La sua azione è valida?', a: ['Sì, è vincolante e può essere soggetta a penalità', 'No, senza puntata di fronte un fold si considera check', 'No, può riprendere le carte se non ha ancora parlato', 'Sì, ma solo se dopo di lui c\'è ancora un giocatore da agire'], why: 'Regola 60: i fold senza puntate di fronte sono vincolanti e possono essere soggetti a penalità.' },
    { id: 't8', cat: T, r: ['R61'], q: 'Un giocatore dice "se tu punti, io rilancio". Com\'è?', a: ['Non standard: a discrezione del TD può essere vincolante', 'Non conta mai, perché parla di un\'azione non ancora avvenuta', 'Va sempre eseguita, se l\'avversario poi punta davvero', 'È un rilancio immediato, anche se nessuno ha puntato'], why: 'Regola 61-A: le dichiarazioni condizionali sono fortemente scoraggiate e possono essere vincolanti e/o soggette a penalità.' },
    { id: 't9', cat: T, r: ['R52'], q: 'A dice "raise" senza importo e B folda subito. Cosa dice la regola?', a: ['B dovrebbe aspettare che l\'importo sia chiaro', 'Il fold di B è annullato e potrà agire di nuovo', 'A deve fare all-in, visto che non ha detto l\'importo', 'A fa il rilancio minimo per forza'], why: 'Regola 52-B: i giocatori devono attendere che l\'ammontare delle puntate sia chiaro prima di agire.' },
    { id: 'e1', cat: E, r: ['R69'], q: 'Un giocatore già fuori dalla mano commenta "avevo due assi". Che regola viola?', a: ['Regola 69, one player to a hand', 'Nessuna, perché è già fuori dalla mano', 'Solo se la mano è in heads-up', 'Regola 30, rabbit hunting'], why: 'Regola 69: i giocatori, nella mano o no, non devono discutere il contenuto di una mano non mostrata, attiva o foldata.' },
    { id: 'e2', cat: E, r: ['R70'], q: 'Un giocatore mostra le carte mentre l\'azione è in corso. La sua mano resta valida?', a: ['Sì, ma può incorrere in penalità a fine mano', 'No, la mano è morta perché le carte sono esposte', 'No, finisce subito nel muck con penalità', 'Solo se è in all-in, altrimenti è morta'], why: 'Regola 70: la mano resta valida. L\'eventuale penalità parte al termine della mano in corso.' },
    { id: 'e3', cat: E, r: ['R74'], q: 'Penalità di un giro con 8 giocatori al tavolo, incluso lui. Quante mani salta?', a: ['8', '7', '9', '1'], why: 'Regola 74-A: una mano per ogni giocatore, lui compreso, al tavolo al momento della penalità, per il numero di giri.' },
    { id: 'e4', cat: E, r: ['R74'], q: 'Cosa succede al posto di un giocatore in penalità?', a: ['Riceve carte e paga bui e ante, ma la mano si folda a fine distribuzione', 'Si salta il posto nella distribuzione e i bui passano al successivo', 'Si danno le carte, ma bui e ante non si pagano finché non torna', 'I suoi gettoni escono dal gioco fino alla fine della penalità'], why: 'Regola 74-C: le carte sono distribuite, bui e ante raccolti, e la mano è foldata al termine della distribuzione.' },
    { id: 'e5', cat: E, r: ['R74'], q: 'Cosa succede ai gettoni di un giocatore squalificato?', a: ['Vengono rimossi dal gioco', 'Vanno al piatto', 'Si dividono tra il tavolo', 'Restano fino a esaurimento'], why: 'Regola 74-D: i gettoni di un giocatore squalificato sono rimossi dal gioco.' },
    { id: 'e6', cat: E, r: ['R67'], q: 'Per errore metti nel muck le carte di un giocatore e non sono identificabili. Cosa gli spetta?', a: ['Nessun rimborso dei call, solo l\'eventuale puntata non ancora chiamata', 'Gli si restituiscono tutte le puntate fatte, visto che è colpa del dealer', 'Metà del piatto, perché l\'errore non è suo', 'Si rigioca la mano con tutti quelli che erano dentro'], why: 'Regola 67-A: il giocatore deve proteggere le carte. Se non sono identificabili al 100% non riavrà i call fatti. Il testo inglese aggiunge che la parte puntata e non ancora chiamata gli viene restituita.' },
    { id: 'e7', cat: E, r: ['R5'], q: 'Un giocatore con mano attiva guarda il telefono. È permesso?', a: ['No, con mani vive non si possono usare dispositivi', 'Sì, purché non telefoni e non faccia rumore al tavolo', 'Sì, se lo tiene sotto il tavolo e non disturba', 'Sì, se è silenziato e non ritarda il gioco'], why: 'Regola 5-C: chi ha una mano viva non può interagire con dispositivi elettronici. E il telefono non può stare sul tavolo (5-B).' },
    { id: 'e8', cat: E, r: ['R3'], q: 'Un giocatore batte sul tavolo. Che azione è?', a: ['Un check', 'Niente, è un gesto non valido', 'Un call', 'Un fold'], why: 'Regola 3-A: battere o picchiettare sul tavolo è un check.' },
    { id: 'e9', cat: E, r: ['R22'], q: 'BB ante: due giocatori a premi vengono eliminati nella stessa mano. Chi si piazza meglio?', a: ['Chi aveva lo stack iniziale maggiore, calcolato dopo l\'ante', 'Chi era più vicino al bottone in quella mano', 'Chi ha il numero di posto più basso', 'Chi ha perso con il punto peggiore allo showdown'], why: 'Regola 22: nei giochi con BBA conta lo stack iniziale maggiore, calcolato dopo il versamento dell\'ante.' },
    { id: 'k1', cat: K, r: ['RP1'], q: 'Chi tiene i bottoni all-in?', a: ['Il dealer, e li mette davanti a chi è all-in', 'I giocatori, che li mettono quando vanno all-in', 'Il floor, che li porta quando c\'è un all-in', 'Il giocatore di bottone, per tutta la mano'], why: 'RP-1: il dealer tiene i bottoni e ne mette uno davanti al giocatore in all-in, ben visibile.' },
    { id: 'k2', cat: K, r: ['RP2'], q: 'Puoi portare le puntate nel piatto mentre il giro è ancora in corso?', a: ['No, è sconsigliato: può creare confusione ed errori', 'Sì, è la procedura corretta per tenere pulito il tavolo', 'Sì, dopo ogni rilancio, così si contano meglio', 'Solo se le puntate sono molte e ingombrano'], why: 'RP-2: è una cattiva pratica. Solo il giocatore che in quel momento deve agire può chiederlo.' },
    { id: 'k3', cat: K, r: ['RP7'], q: 'Il tuo cambio cade a un minuto da una pausa programmata. Che dovresti fare?', a: ['Posticiparlo: il cambio si ferma 90 secondi prima di pause e livelli', 'Cambiare subito, la pausa non c\'entra con il cambio dealer', 'Finire la mano in corso e poi dare il cambio come previsto', 'Posticiparlo solo se mancano meno di 30 secondi, altrimenti cambiare'], why: 'RP-7: il TDA raccomanda di posticipare i cambi che cadono 90 secondi prima di una pausa programmata o di un cambio livello.' },
    { id: 'k4', cat: K, r: ['RP12'], q: 'Quando annunci gli importi delle puntate?', a: ['Sempre quelle non all-in; gli all-in solo se lo chiede chi deve agire', 'Mai, le annunci solo quando un giocatore te lo chiede', 'Sempre tutte, anche gli all-in, appena il giocatore le mette avanti', 'Gli all-in sempre, le altre puntate solo se qualcuno lo chiede'], why: 'RP-12: il dealer annuncia regolarmente le puntate non all-in. Gli all-in si contano solo su richiesta del giocatore che vi fa fronte.' },
    { id: 'k5', cat: K, r: ['RP15'], q: 'Cosa devi fare quando dai il cambio al collega?', a: ['Passargli le info: bui, warning, penalità, comportamenti molesti', 'Niente, il nuovo dealer si informa da solo con il floor', 'Annunciare ai giocatori il cambio e il nome del nuovo dealer', 'Contare insieme a lui ogni stack e il totale dei gettoni al tavolo'], why: 'RP-15-A: chi esce informa chi entra su bui, warning o penalità e comportamenti di disturbo.' },
    { id: 'k6', cat: K, r: ['RP24'], q: 'Un giocatore ti chiede "quanto è la puntata su di me?". Come rispondi?', a: ['"Cinquemila"', '"Solo cinquemila"', '"Poco, cinquemila"', '"Vale la pena, cinquemila"'], why: 'RP-24: si risponde col numero secco e la casa non deve dare indicazioni strategiche.' },
    { id: 'k7', cat: K, r: ['RP8'], q: 'Hand for hand: un giocatore all-in viene chiamato. Che fai con le carte?', a: ['Restano coperte e aspetti istruzioni', 'Le fai scoprire subito, come sempre', 'Giri subito il board fino al river', 'Chiedi ai giocatori se vogliono scoprirle'], why: 'RP-8-F: le carte restano coperte e il dealer non procede finché non riceve istruzioni.' },
    { id: 'k8', cat: K, r: ['RP11'], q: 'Con il big blind ante, un giocatore non copre buio e ante. Cosa si paga per primo?', a: ['Il big blind, poi l\'ante con quello che resta', 'L\'ante, poi il big blind con quello che resta', 'In parti uguali tra buio e ante', 'Quello che sceglie il giocatore, prima di vedere le carte'], why: 'RP-11: il TDA consiglia il formato BBA con calcolo big blind first.' },
    { id: 'k9', cat: K, r: ['RP20'], q: 'A un minuto dall\'inizio del livello il floor annuncia "dealers prepare your decks". Cosa fai?', a: ['Con almeno 2 giocatori seduti fai il wash e prepari il mazzo', 'Inizi subito a mescolare e distribuisci la prima mano appena puoi', 'Aspetti che siano seduti tutti i giocatori prima del wash', 'Fai il wash solo se il tavolo è completo, altrimenti aspetti'], why: 'RP-20: con almeno 2 giocatori al tavolo il dealer fa il wash e ricompone il mazzo, per essere pronto allo shuffle quando inizia il livello.' },
    { id: 'k10', cat: K, r: ['RP21', 'R56'], q: 'Quando viene conteggiato il piatto?', a: ['Solo negli eventi pot-limit', 'Sempre, se un giocatore lo chiede', 'Solo al river, prima dello showdown', 'Solo in heads-up'], why: 'RP-21: il piatto si conteggia solo negli eventi pot-limit. Su richiesta può essere steso per vedere meglio i gettoni.' },
    { id: 'd17', cat: D, r: ['R38'], q: 'I bui già messi contano per l\'azione sostanziale?', a: ['No, non contano', 'Sì, contano come due azioni', 'Conta solo il big blind', 'Contano dopo il primo giro'], why: 'Il testo inglese della regola 38 dice che i bui già messi non contano per l\'azione sostanziale. Nella traduzione italiana questa frase manca.' },
    { id: 'm15', cat: M, r: ['R25'], q: 'Inizia un nuovo livello proprio durante il cambio dealer. Con che limiti dà la prossima mano il dealer che entra?', a: ['Dà una mano al livello precedente', 'Usa subito i limiti del nuovo livello', 'Aspetta che il floor gli dica i limiti', 'Salta una mano'], why: 'Testo inglese della regola 25-B: se un nuovo livello inizia durante il cambio dealer, il dealer in arrivo dà una mano al livello precedente. Nella traduzione italiana la frase manca.' },
    { id: 'sd20', cat: S, r: ['R18'], q: 'Showdown senza all-in. Al river A punta, B chiama, C chiama, nessuno rilancia. Nessuno mostra spontaneamente. Chi deve mostrare per primo?', a: ['A, che ha fatto l\'unica azione aggressiva del river', 'C, l\'ultimo che ha chiamato la puntata', 'B, il primo che ha risposto alla puntata', 'Il primo a sinistra del bottone, visto che nessuno rilancia'], why: 'Regola 18-A: mostra per primo chi ha fatto l\'ultima azione aggressiva nell\'ultimo giro di puntate. Chi chiama non conta.' },
    { id: 'e10', cat: E, r: ['R70'], q: 'Sei l\'ultimo a dover agire. Prima di dichiarare, un giocatore gira le sue carte sul tavolo. Cosa succede alla sua mano?', a: ['Resta valida, ma può essere penalizzato a fine mano', 'È morta, perché ha mostrato in anticipo', 'Resta valida e non può essere penalizzato', 'È morta solo se le carte erano coperte e le ha girate'], why: 'Regola 70: esporre le carte con azione pendente, anche per chi agisce per ultimo, può dare una penalità ma non una mano morta. La penalità parte alla fine della mano.' },
    { id: 'e11', cat: E, r: ['R70'], q: 'Come si dovrebbe foldare?', a: ['Spingendo le carte in avanti, basse sul tavolo', 'Lanciandole in alto verso il dealer', 'Girandole a faccia in su per far vedere che il fold è giusto', 'Mettendole sopra il piatto'], why: 'Regola 70: le carte si spingono in avanti, basse sul tavolo, senza esporle né lanciarle in alto (helicopter).' },
    { id: 'e12', cat: E, r: ['R71'], q: 'Al river, ultimo a parlare, un giocatore ha i nuts esclusivi e fa check dopo il check dell\'avversario. È soft play automatico?', a: ['No, il TD valuta in base alla situazione', 'Sì, penalità automatica', 'Sì, ma solo se è in heads-up', 'No, e il TD non può intervenire in nessun caso'], why: 'Regola 71: checkare i nuts esclusivi da ultimo al river non è una violazione automatica; si applica la discrezione del TD.' },
    { id: 'e13', cat: E, r: ['R71'], q: 'Due giocatori si passano gettoni di proposito per favorire uno dei due. Che conseguenza prevede la regola?', a: ['Squalifica', 'Un giro di penalità', 'Un avvertimento verbale', 'La perdita di una parte dello stack'], why: 'Regola 71: chip dumping e altre forme di collusione portano alla squalifica. Il soft play invece può portare a penalità, anche con perdita di gettoni.' },
    { id: 'e14', cat: E, r: ['R5'], q: 'Un giocatore appoggia il telefono sul tavolo, spento e girato, e non ha una mano viva. È consentito?', a: ['No, i dispositivi non possono stare sul tavolo', 'Sì, se è spento e girato a faccia in giù', 'Sì, purché sia spento e lui non abbia mani vive', 'Sì, se avvisa il dealer prima di appoggiarlo'], why: 'Regola 5-B: telefoni e altri dispositivi non possono appoggiare sul tavolo. Il divieto di usarli con mano viva (5-C) è un\'altra cosa.' },
    { id: 'e15', cat: E, r: ['R5'], q: 'Un giocatore, fuori dalla mano, consulta un\'app con i charts di strategia. Può?', a: ['No, app e charts di strategia non si usano al tavolo', 'Sì, perché il divieto vale solo per chi ha una mano viva', 'Sì, finché non ritarda il gioco e non disturba', 'Sì, se lo dice prima agli avversari al tavolo'], why: 'Regola 5-D: betting app, charts e altri strumenti di strategia non si usano al tavolo. Il divieto vale anche fuori dalla mano.' },
    { id: 'e16', cat: E, r: ['R5'], q: 'Un giocatore indossa occhiali smart con una camera, spenta. Cosa dice la regola?', a: ['Sono vietati, salvo autorizzazione del TD', 'Vanno bene se la camera è spenta e non registra', 'Vanno bene se il dealer lo accetta', 'Vanno bene se registrano solo l\'audio'], why: 'Regola 5-A: dispositivi indossabili capaci di registrare o comunicare di nascosto, compresi gli occhiali smart, sono vietati al tavolo salvo autorizzazione del TD.' },
    { id: 'e17', cat: E, r: ['R65'], q: 'Un giocatore si mette dei gettoni in tasca e va via dal tavolo. Cosa prevede la regola?', a: ['Perde i gettoni, che escono dal gioco, e può essere squalificato', 'Riceve un avvertimento e li rimette sul tavolo', 'I gettoni vanno nel piatto della mano', 'Non succede nulla se li riporta al tavolo entro la mano successiva'], why: 'Regola 65: chi tiene o trasporta gettoni fuori dalla vista li perde e può essere squalificato. I gettoni persi escono dal gioco.' },
    { id: 'e18', cat: E, r: ['R35', 'R74'], q: 'Un giocatore evita di proposito di pagare i bui. Cosa si applica?', a: ['Una penalità, regola 74-B', 'Nessuna penalità se poi paga quelli arretrati', 'La squalifica immediata', 'Solo un cambio di tavolo'], why: 'Regola 35: chi evita volontariamente un buio incorre in una penalità (regola 74-B).' },
    { id: 'e19', cat: E, r: ['R33'], q: 'Un giocatore all-in, con la mano ancora in corso, si alza e lascia il tavolo. Può?', a: ['No, chi ha una mano viva deve restare, anche se è all-in', 'Sì, perché essendo all-in non deve più fare nessuna azione', 'Sì, se torna prima dello showdown', 'Sì, se avvisa il dealer'], why: 'Regola 33: chi ha una mano viva, anche all-in, resta al tavolo per tutti i giri e per lo showdown. Alzarsi può dare una penalità.' },
    { id: 'e20', cat: E, r: ['R73'], q: 'Un giocatore lancia i gettoni della puntata sopra il piatto, invece di metterli davanti a sé. Che regola viola?', a: ['Regola 73: splashing the pot, tra le condotte vietate', 'Regola 58: è una string bet', 'Nessuna, se l\'importo puntato è giusto e si conta', 'Regola 70: esposizione delle carte con azione in corso'], why: 'Regola 73: tra le condotte vietate c\'è mettere i gettoni sopra il piatto o fuori dalla portata del dealer.' },
    { id: 'e21', cat: E, r: ['R72'], q: 'Un giocatore commenta ad alta voce, prendendola in giro, la giocata di un altro. Che succede?', a: ['È una condotta vietata dalla regola 72 e può essere penalizzata', 'Niente, è libertà di parola finché non insulta qualcuno direttamente', 'Solo se il commento è fatto mentre la mano è ancora in corso', 'Solo se lo ripete tre volte'], why: 'Regola 72: critiche, derisioni o commenti negativi sul gioco altrui sono condotta vietata. Il TD ha discrezione sulla penalità.' },
    { id: 'e22', cat: E, r: ['R4'], q: 'Un giocatore tiene cappuccio e occhiali scuri che gli nascondono il viso. Cosa può chiedergli lo staff?', a: ['Di toglierli, se impediscono di identificarlo o disturbano', 'Niente, è un suo diritto', 'Di toglierli solo se lo chiede un altro giocatore al tavolo', 'Di toglierli solo al cambio livello'], why: 'Regola 4: i giocatori devono essere sempre identificabili. Lo staff può chiedere di togliere ciò che impedisce l\'identificazione o è un disturbo.' },
    { id: 'e23', cat: E, r: ['R74'], q: 'Un giocatore in penalità ha pochi gettoni e i bui continuano a girare. Cosa può succedere?', a: ['Può essere eliminato dai bui e dalle ante pur essendo assente', 'Niente: finché è in penalità bui e ante non gli vengono prelevati', 'Viene squalificato quando finisce lo stack', 'Il floor gli rimborsa i bui pagati'], why: 'Regola 74-A: chi è lontano dal tavolo o in penalità può essere "anted" o "blinded" fuori dal torneo.' },
    { id: 'm16', cat: M, r: ['R8'], q: 'Un giocatore si siede per errore al posto sbagliato, con lo stack corretto. Cosa si fa?', a: ['Si sposta al posto giusto con lo stack che ha in quel momento', 'Gioca da lì fino al cambio livello, poi si sposta al suo posto', 'Salta un giro di mani', 'Torna allo stack iniziale'], why: 'Regola 8: un giocatore al posto sbagliato ma con lo stack corretto si sposta al posto giusto con il totale attuale delle sue fiche.' },
    { id: 'm17', cat: M, r: ['R7'], q: 'Un giocatore ha ricevuto le fiche ma non è ancora seduto al suo tavolo. È nel torneo?', a: ['Sì, chi ha i gettoni è nel torneo e va subito al tavolo', 'No, entra nel torneo solo dopo la prima mano giocata', 'No, finché non si siede e paga il suo primo buio', 'Sì, ma può sedersi con calma alla fine del livello in corso'], why: 'Regola 7: chi è in possesso di gettoni è nel torneo. Deve andare subito al tavolo assegnato.' },
    { id: 'm18', cat: M, r: ['R9'], q: 'Quante fiche riceve un giocatore che si registra in ritardo o un alternate?', a: ['Uno stack pieno', 'Metà dello stack', 'Lo stack medio del torneo', 'Quanto resta nella cassa'], why: 'Regola 9-A: alternate, late registration e re-entry ricevono stack pieni.' },
    { id: 'm19', cat: M, r: ['R11'], q: 'Un giocatore arrivato da un tavolo rotto si siede nella posizione di big blind. Riceve le carte?', a: ['Sì, e gioca la mano come big blind', 'No, aspetta la mano dopo', 'Sì, ma solo se paga un buio extra', 'No, il big blind non può essere assegnato a un nuovo giocatore'], why: 'Regola 11-A: i giocatori da tavoli rotti possono avere qualunque posto, anche small blind, big blind o bottone, e ricevono le carte tranne tra small blind e bottone.' },
    { id: 'm20', cat: M, r: ['R12'], q: 'Bilanciamento di un tavolo corto: chi si sposta e dove?', a: ['Il prossimo big blind, nella posizione peggiore, anche se fa il BB due volte', 'Chi ha lo stack più corto, nel posto più vicino al bottone del tavolo', 'Il prossimo small blind, nella posizione peggiore del nuovo tavolo', 'Il prossimo big blind, ma mai in un posto dove farebbe il BB due volte'], why: 'Regola 12-A: si sposta chi sarebbe il prossimo big blind, nella posizione peggiore, anche se questo significa big blind due volte. La posizione peggiore non è mai lo small blind.' },
    { id: 'm21', cat: M, r: ['R12'], q: 'Un tavolo ha 2 giocatori in meno del tavolo più pieno, per eliminazione, e i bui lo toccano. Il gioco si ferma?', a: ['No, si ferma con 3 o più giocatori in meno', 'Sì, subito, appena i bui toccano quel tavolo', 'Sì, ma solo in heads-up', 'No, il gioco non si ferma mai'], why: 'Regola 12-D: il gioco si ferma sui tavoli con 3 o più giocatori in meno del tavolo più pieno, una volta toccati i bui. Il TD può anche rinunciare a fermarlo.' },
    { id: 'm22', cat: M, r: ['R29'], q: 'Un giocatore dichiara che farà il re-buy prima della mano. Cosa succede?', a: ['Gioca con le fiche dietro e deve fare il re-buy', 'Può cambiare idea, purché non abbia ancora visto le carte', 'Salta la mano finché non paga', 'Il re-buy è facoltativo fino al flop'], why: 'Regola 29: i giocatori non possono saltare una mano. Chi dichiara il re-buy prima della mano gioca con fiche dietro e deve farlo.' },
    { id: 'm25', cat: M, r: ['R6'], q: 'Chi stabilisce in che lingua si può parlare al tavolo?', a: ['La casa, con avviso chiaro al tavolo', 'Il dealer', 'I giocatori, a maggioranza', 'Il regolamento TDA, che impone l\'inglese ovunque'], why: 'Regola 6: la casa indica e annuncia chiaramente la lingua o le lingue ammesse al tavolo.' },
    { id: 'd18', cat: D, r: ['R37'], q: 'Cominci la mano e dai la prima carta al posto sbagliato, non allo small blind. Cosa fai?', a: ['Misdeal', 'Ridai la carta al posto giusto e continui', 'Scambi le due carte tra i giocatori', 'È misdeal solo se qualcuno protesta'], why: 'Regola 37-A: la prima carta distribuita al posto sbagliato è un misdeal.' },
    { id: 'd19', cat: D, r: ['R37'], q: 'Nella distribuzione iniziale una sola carta risulta girata al contrario (boxed). È misdeal?', a: ['No, la regola parla di 2 o più carte boxed', 'Sì, sempre', 'Sì, se la carta boxed viene vista da più di un giocatore', 'Sì, se finisce al giocatore di bottone'], why: 'Regola 37-A: sono misdeal 2 o più carte boxed nella distribuzione iniziale. Una sola non basta.' },
    { id: 'd20', cat: D, r: ['R37', 'R39'], q: 'Scopri che un giocatore al posto 5, non il bottone, ha ricevuto 3 carte. Nessuno ha ancora agito. Cosa fai?', a: ['Misdeal: numero sbagliato di carte', 'Togli una carta a caso e continui', 'Il giocatore folda e si prosegue', 'È misdeal solo se è lo small blind'], why: 'Regola 37-A: dare un numero sbagliato di carte a un giocatore è misdeal. L\'eccezione è il bottone, regola 39.' },
    { id: 'd22', cat: D, r: ['R37', 'R32'], q: 'C\'è un misdeal. Un giocatore, che era dealt-in, non era al posto durante la distribuzione originale. Che succede nella nuova mano?', a: ['Riceve le carte e può giocare la nuova mano', 'Salta la nuova mano', 'Gioca solo se paga un buio extra di penalità', 'Entra solo alla mano dopo'], why: 'Regola 37-C: le carte vengono date anche ai giocatori che erano dealt-in ma non al posto per la distribuzione originale, e possono giocare la nuova mano.' },
    { id: 'd23', cat: D, r: ['R37'], q: 'A metà mano, dopo azione sostanziale, trovi un jolly nel mazzo in una partita di hold\'em. Cosa fai?', a: ['Mazzo compromesso: fermi il gioco e restituisci tutte le puntate', 'Togli il jolly e continui, perché c\'è già stata azione sostanziale', 'Finisci la mano e poi fai sostituire il mazzo dal floor', 'Dichiari misdeal e ridistribuisci la mano con un mazzo nuovo'], why: 'Regola 37-E: un mazzo con una carta non standard per il gioco è compromesso. Si ferma tutto e si restituiscono le puntate, indipendentemente dall\'azione sostanziale.' },
    { id: 'd25', cat: D, r: ['R39'], q: 'Il giocatore di bottone ha una sola carta ma agisce lo stesso, con un check. Cosa succede alla sua mano?', a: ['È morta', 'Ridai la carta e resta valida', 'Misdeal', 'Decide il floor se ridare la carta'], why: 'Regola 39: se il bottone agisce con troppe poche carte, check o puntata, la sua mano è morta.' },
    { id: 'd27', cat: D, r: ['R38'], q: 'Preflop i primi due giocatori foldano. C\'è azione sostanziale?', a: ['No, sono due azioni senza gettoni', 'Sì, bastano due azioni', 'Sì, perché i bui contano come azione', 'Dipende dal livello'], why: 'Regola 38: serve un\'azione con gettoni più un\'altra azione, oppure tre azioni qualunque. Due fold non bastano e i bui già messi non contano.' },
    { id: 'b31', cat: B, r: ['R42', 'I42-A'], q: 'Un giocatore spinge chiaramente 4.000 in gettoni e subito dopo dice "cinquemila". Qual è la puntata?', a: ['4.000, perché il primo metodo usato definisce la puntata', '5.000, perché prevale la voce', '5.000, perché tra voce e gettoni si prende l\'importo più alto', 'Decide sempre il floor, senza criteri'], why: 'Regola 42-A: se usa entrambi i metodi, il primo effettuato definisce la puntata. Se sono in contrasto o non è chiaro, decide il TD.' },
    { id: 'b32', cat: B, r: ['R44'], q: 'Un giocatore dichiara "raise a 8.000" e poi mette i gettoni in due movimenti. È valido?', a: ['Sì, ha dichiarato il totale prima di mettere i gettoni', 'No, è una string bet', 'Sì, ma solo se tra i due movimenti non fa nessuna pausa', 'No, vale solo il call'], why: 'Regola 44: il rilancio è valido se tutto in un movimento oppure se il totale è dichiarato prima di mettere i gettoni.' },
    { id: 'b34', cat: B, r: ['R61'], q: 'A dice "bet" senza importo e B chiama subito, prima di sapere quanto. Cosa fa il TD?', a: ['Decide come meglio si adatta, anche obbligando B a chiamare qualunque importo', 'B può ritirare il call e decidere di nuovo, appena A dice l\'importo esatto', 'La puntata si considera la minima, e B chiama quella', 'La puntata è annullata e A deve ripeterla con l\'importo'], why: 'Regola 61-B: se B chiama prima che l\'importo esatto sia noto, il TD decide, anche obbligando B a chiamare qualsiasi importo.' },
    { id: 'b35', cat: B, r: ['R3'], q: 'Un giocatore che deve rispondere a una puntata chiede ad alta voce "ha rilanciato?". Che rischio c\'è?', a: ['Può valere come dichiarazione di rilancio e diventare vincolante', 'Nessuno: una domanda non è mai vincolante, qualunque parola contenga', 'Si considera un fold automatico, perché ha parlato fuori turno', 'Prende sempre una penalità di un giro per linguaggio non standard'], why: 'Regola 3-B: usare termini ufficiali in una domanda può essere ritenuto vincolante. Meglio chiedere "qual è stata la sua azione?".' },
    { id: 'b36', cat: B, r: ['R43'], q: 'Bui 2.000-4.000. A punta 50.000 e B mette in silenzio un solo gettone da 1.000. Come può essere trattato?', a: ['Azione non standard: il TD può considerarla call completo e penalizzarlo', 'Come un call da 1.000, e resta in mano solo per quell\'importo', 'Come un fold, e il gettone da 1.000 resta nel piatto', 'Come un rilancio minimo, perché il gettone è stato messo in silenzio'], why: 'Regola 43: spingere in silenzio un gettone minuscolo rispetto alla puntata è non standard, scoraggiato, soggetto a penalità e interpretato dal TD, anche come call completo.' },
    { id: 't10', cat: T, r: ['R55', 'I55-A1'], q: 'Il posto 6 chiama fuori turno, mentre tocca al posto 5. Il posto 5 folda. Che succede al call del 6?', a: ['Resta valido: il fold del 5 non cambia l\'azione', 'Viene annullato, perché un fold cambia sempre l\'azione', 'Il 6 riprende i gettoni e sceglie di nuovo', 'Il 6 è fuori dalla mano'], why: 'Regola 55-A1: un check, call o fold del giocatore giusto non cambia l\'azione, quindi l\'azione fuori turno resta vincolante, con possibile penalità.' },
  ];
  root.QUIZ = QUIZ;
  if (typeof module !== 'undefined' && module.exports) module.exports = QUIZ;
})(typeof globalThis !== 'undefined' ? globalThis : this);
